func groupAnagrams(strs []string) [][]string {
    m := make(map[string][]string)
    for _, s := range strs {
        b := []byte(s)
        sort.Slice(b, func(i, j int) bool { return b[i] < b[j] })
        key := string(b)
        m[key] = append(m[key], s)
    }
    res := make([][]string, 0, len(m))
    for _, v := range m {
        res = append(res, v)
    }
    return res
}

func groupAnagrams(strs []string) [][]string {
    m := make(map[[26]byte][]string)
    for _, s := range strs {
        var key [26]byte
        for _, c := range s {
            key[c-'a']++
        }
        m[key] = append(m[key], s)
    }
    res := make([][]string, 0, len(m))
    for _, v := range m {
        res = append(res, v)
    }
    return res
}
